//   2. Run `npm run sync:regional-config` — this regenerates
//      sites.generated.js, countries.generated.ts, and
//      contentfulMapping.generated.ts from Business Manager in one pass (the
//      site must already exist in BM). Do NOT hand-edit locale/currency data
//      in countries.ts or contentfulMapping.ts — it's derived now.
//   3. Add the new slug's business-logic entry to COUNTRY_OVERLAY in
//      overrides/app/config/countries.ts (shippingCountry, checkoutOwner,
//      globalEPricing, boutiqueRegion) — that part is still hand-maintained,
//      since Business Manager has no concept of it.
//   4. If it needs e2e coverage, add it to e2e/fixtures/site.overlay.js too.
//   5. Ensure a compiled translation exists in
//      overrides/app/static/translations/compiled/.
module.exports = [
  // AU — root (no prefix), x-default hreflang, gated to AU/Oceania IPs
  { id: 'ZimmermannAU', locales: [{ id: 'en' }] },
  // US domestic — /us/ via SFCC
  { id: 'ZimmermannUS', locales: [{ id: 'en-US', alias: 'us' }] },
  // US international — /en-ca/ — Global-e checkout (Canada + all other Americas)
  { id: 'ZimmermannUSIntl', locales: [{ id: 'en-CA', alias: 'en-ca' }] },
  // UK — /uk/ — SFCC checkout
  { id: 'ZimmermannUK', locales: [{ id: 'en-GB', alias: 'uk' }] },
  // EU domestic — four single-locale PWA sites, all backed by SFCC ZimmermannEU
  { id: 'ZimmermannEUen', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'en-GB', alias: 'en-eu' }] },
  { id: 'ZimmermannEUfr', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'fr', alias: 'fr-eu' }] },
  { id: 'ZimmermannEUit', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'it', alias: 'it-eu' }] },
  { id: 'ZimmermannEUes', sfccSiteId: 'ZimmermannEU', locales: [{ id: 'es', alias: 'es-eu' }] },
  // EU international — /en-ch/ — Global-e checkout (non-EU Europe + Africa + ROW)
  { id: 'ZimmermannEUIntl', locales: [{ id: 'en-CH', alias: 'en-ch' }] },
  // HK — /hk/ — Global-e checkout (Asia-Pacific)
  { id: 'ZimmermannHK', locales: [{ id: 'en-HK', alias: 'hk' }] },
  // ME — /en-ae/ — Global-e checkout (Middle East)
  { id: 'ZimmermannME', locales: [{ id: 'en-AE', alias: 'en-ae' }] },
];

